#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024

int main(int argc, char *argv[])
{
    const char *input;
    char norm[MAX_LEN + 1];
    size_t i, len = 0;

    if (argc > 1) {
        input = argv[1];
    } else {
        input = "";
    }

    if (strlen(input) > MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }

    for (i = 0; input[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            if (len >= MAX_LEN) break; // safety, should not happen
            norm[len++] = (char)tolower(c);
        }
    }
    norm[len] = '\0';

    int is_pal = 1;
    for (i = 0; i < len / 2; ++i) {
        if (norm[i] != norm[len - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
